// Validate shared secret from GitHub Actions header x-webhook-secret
const expected = $env.WEBHOOK_SHARED_SECRET || '';
const headers = $json.headers || {};
const provided = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';

if (!expected) {
  throw new Error('WEBHOOK_SHARED_SECRET is not set in the n8n environment');
}
if (provided !== expected) {
  throw new Error('Invalid x-webhook-secret');
}

const body = $json.body || $json;
const required = ['run_id', 'repo', 'branch', 'commit', 'actor', 'owner'];
for (const key of required) {
  if (!body[key]) {
    throw new Error(`Missing required payload field: ${key}`);
  }
}

return [{ json: { ...body, secret_ok: true } }];

// CONFIGURE: Prefer minting the JWT inside n8n with your App private key,
// or replace this node with a pre-minted installation token credential.
// This reconstructed flow expects an installation token provided via env for simplicity.
const token = $env.GITHUB_INSTALLATION_TOKEN || '';
if (!token) {
  throw new Error('Set GITHUB_INSTALLATION_TOKEN (mint via scripts/mint_installation_token.sh) or replace this node with GitHub App JWT → installation token HTTP calls. See docs/reconstruction-guide.md');
}
return [{ json: { ...$json, installation_token: token } }];

// Merge GitHub context for the LLM prompt.
const base = $('CONFIGURE GitHub Token').item.json;
const commit = $('GET Commit + Files').item.json;
const jobs = $('GET Workflow Jobs').item.json;

const files = (commit.files || []).map(f => ({
  filename: f.filename,
  status: f.status,
  patch: (f.patch || '').slice(0, 4000)
}));

const jobSummary = (jobs.jobs || []).map(j => ({
  name: j.name,
  conclusion: j.conclusion,
  html_url: j.html_url
}));

const prompt = [
  'You are a senior code reviewer. CI failed. Produce a structured review with:',
  '1) assessment scores (1-10) for correctness, maintainability, test quality, security',
  '2) identified issues with file references',
  '3) concrete suggested fixes',
  '',
  `Repo: ${base.repo}`,
  `Branch: ${base.branch}`,
  `Commit: ${base.commit}`,
  `Actor: ${base.actor}`,
  `Run: ${base.run_id}`,
  '',
  'Changed files:',
  JSON.stringify(files, null, 2),
  '',
  'Job results:',
  JSON.stringify(jobSummary, null, 2)
].join('\n');

return [{
  json: {
    ...base,
    files,
    jobSummary,
    prompt,
    commit_message: commit.commit?.message || ''
  }
}];

// CONFIGURE: Replace this stub with an official LLM node (OpenAI / Google Gemini / Anthropic).
// The original provider and prompt were not recovered.
const prompt = $json.prompt;
const stub = [
  '## CI Failure Review (stub — replace with real LLM node)',
  '',
  'Prompt length: ' + prompt.length + ' chars',
  'Files: ' + ($json.files || []).map(f => f.filename).join(', '),
  '',
  'Configure an LLM credential in n8n and swap this node for a real model call.'
].join('\n');

return [{ json: { ...$json, review_markdown: stub } }];
